(function(){
  var D=Arena.UI.PointerLockDiag;
  var fail=[];
  if(!D) return {assert:false, fail:['Arena.UI.PointerLockDiag no está cargado']};
  var p=D.create(Arena.Game);
  if(!p||!p.root||!p.root.parentNode) fail.push('el panel no se inserta en el documento');
  var texto=p?p.root.textContent:'';
  var necesarios=['Pointer Lock activo','cursor desaparece','1:1','vuelve el cursor','NO el cuerpo'];
  for(var i=0;i<necesarios.length;i++){
    if(texto.indexOf(necesarios[i])<0) fail.push('falta la comprobación: '+necesarios[i]);
  }
  var rep=p?p.report():'';
  if(rep.indexOf('POINTER LOCK')<0) fail.push('el informe no se genera');
  D.toggle(Arena.Game);
  var cerrado=!document.body.textContent.match(/Diagnóstico · Pointer Lock/);
  if(!cerrado) fail.push('el panel no se cierra');
  return {assert:!fail.length, fail:fail, comprobaciones:necesarios.length};
})()

(function(){
  var G=Arena.Game,W=G.world,D=Arena.UI.PointerLockDiag;
  var p=W.getPlayer();
  var antes=[p.hp,p.pos.x,p.pos.z,p.yaw,p.resource].join(',');
  D.create(G);
  for(var i=0;i<20;i++) W.stepSeconds(1/30);
  var conPanel=[p.hp,p.pos.x,p.pos.z,p.yaw,p.resource].join(',');
  D.toggle(G);
  /* Lo que se comprueba no es que los números no cambien —la simulación
     avanza— sino que el panel no aparece en ninguna ruta de escritura. */
  var src=D.create.toString();
  var fail=[];
  if(/\.hp\s*=|\.resource\s*=|\.pos\.|cooldowns\[|\.yaw\s*=/.test(src)) fail.push('el diagnóstico escribe estado de simulación');
  return {assert:!fail.length, fail:fail, muestra:conPanel.slice(0,40)};
})()

(function(){
  var G=Arena.Game, canvas=document.getElementById('gl');
  var pedido=0;
  var orig=canvas.requestPointerLock;
  canvas.requestPointerLock=function(){ pedido++; if(orig) try{orig.call(canvas);}catch(e){} };
  function m(t,b,x,y){ var ev=new MouseEvent(t,{bubbles:true,clientX:x,clientY:y,button:b,buttons:b===0?1:2}); (t==='mousemove'?window:canvas).dispatchEvent(ev); }
  m('mousedown',0,700,380);
  for(var i=1;i<=14;i++) m('mousemove',0,700+i*9,380);
  m('mouseup',0,830,380);
  canvas.requestPointerLock=orig;
  /* Esto SÍ es automatizable: que el juego lo pida. Lo que el navegador
     headless no hace es concederlo. */
  return {assert:pedido>0, fail: pedido>0?[]:['el arrastre no solicitó Pointer Lock'], veces:pedido};
})()

(function(){
  /* Se DOCUMENTA la limitación con una medición, no se afirma de memoria.
     Si algún día un headless lo concediera, esta sonda lo diría y la fila
     podría pasar a VERIFIED automáticamente. */
  var concedido = document.pointerLockElement === document.getElementById('gl');
  return {assert:true, estado: concedido?'CONCEDIDO':'NO CONCEDIDO',
          contextoSeguro: !!window.isSecureContext,
          soportado: !!document.getElementById('gl').requestPointerLock,
          veredicto: concedido ? 'VERIFIED' : 'MANUAL_BROWSER_REQUIRED'};
  })()
